// Kill Team (2024) data, generated by tools/sync-killteam.py from BSData's
// catalogues, and the helpers that read it. Team files are fetched on demand
// and cached by the service worker, like the 40k points data.

const teams = new Map();
const loaded = new Map();
let indexPromise = null;
let rulesPromise = null;
let rules = null;

const json = (url) => fetch(url).then((r) => (r.ok ? r.json() : Promise.reject(new Error("http " + r.status))));

export function index() {
  if (!indexPromise) indexPromise = json("./data/kt/index.json").catch((e) => { indexPromise = null; throw e; });
  return indexPromise;
}

export function loadRules() {
  if (!rulesPromise) {
    rulesPromise = json("./data/kt/rules.json")
      .then((r) => { rules = r; return r; })
      .catch((e) => { rulesPromise = null; throw e; });
  }
  return rulesPromise;
}

export function team(slug) {
  if (!slug) return Promise.resolve(null);
  if (!teams.has(slug)) {
    teams.set(slug, json("./data/kt/" + encodeURIComponent(slug) + ".json")
      .catch((e) => { teams.delete(slug); throw e; }));
  }
  return teams.get(slug);
}

/** Synchronous access to a team already fetched by ensure(). */
export const got = (slug) => loaded.get(slug) || null;

export async function ensure(slugs) {
  const wanted = [...new Set(slugs.filter((s) => s && !loaded.has(s)))];
  await Promise.all(wanted.map((s) => team(s).then((t) => loaded.set(s, t)).catch(() => {})));
  try { await loadRules(); } catch (e) { /* glossary is optional */ }
}

export const opType = (t, name) => (t && t.operatives.find((o) => o.name === name)) || null;

/** The default pick for each option group: the first choice, where one is required. */
export function defaultChoices(type) {
  const out = {};
  for (const g of type.options) if (g.choices.length && (g.min || 0) > 0) out[g.name] = g.choices[0].name;
  return out;
}

/** An operative's weapons: its fixed kit plus whatever its chosen options carry. */
export function weapons(type, choices) {
  if (!type) return [];
  const out = type.weapons.slice();
  for (const g of type.options) {
    const pick = g.choices.find((c) => c.name === (choices || {})[g.name]);
    if (pick) out.push(...pick.weapons);
  }
  const seen = new Set();
  return out.filter((w) => {
    const k = w.name + "|" + w.atk + "|" + w.hit + "|" + w.dmg + "|" + w.wr;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

// "Lethal 5+" and "Torrent 2\"" are instances of the glossary's "Lethal x+"
// and "Torrent x", so normalise numbers and inches before matching.
const ruleKey = (s) => s.toLowerCase().replace(/\d+(?:\.\d+)?/g, "x").replace(/["”″]/g, "").replace(/\s+/g, " ").trim();

/** Glossary entries for the weapon rules an operative's weapons use. */
export function weaponRules(ws) {
  if (!rules) return [];
  const byKey = new Map(rules.weaponRules.map((r) => [ruleKey(r.name), r]));
  const out = [];
  for (const w of ws) {
    for (const token of (w.wr || "").split(",")) {
      const r = byKey.get(ruleKey(token));
      if (r && !out.includes(r)) out.push(r);
    }
  }
  return out;
}

export const universalEquipment = () => (rules ? rules.equipment : []);

/**
 * Soft composition checks: a leader, the operative count, and per-type limits.
 * BSData encodes the common limits; unusual teams have rules it doesn't, so
 * these are warnings, never blocks.
 */
export function check(t, roster) {
  const issues = [];
  if (!t) return issues;
  const types = roster.operatives.map((o) => opType(t, o.type));
  const leaders = types.filter((x) => x && x.leader).length;
  const ops = types.filter((x) => x && x.keywords.includes("Operative")).length;

  if (t.operatives.some((x) => x.leader)) {
    if (leaders === 0) issues.push("No leader yet.");
    else if (leaders > 1) issues.push(leaders + " leaders; a kill team has one.");
  }
  const c = t.composition && t.composition.operative;
  if (c) {
    if (c.max != null && ops > c.max) issues.push(ops + " operatives; the team allows " + c.max + ".");
    else if (c.min != null && ops < c.min) issues.push(ops + " of " + c.min + " operatives chosen.");
  }
  const counts = new Map();
  for (const o of roster.operatives) counts.set(o.type, (counts.get(o.type) || 0) + 1);
  for (const [name, n] of counts) {
    const x = opType(t, name);
    if (x && x.max != null && n > x.max) issues.push(n + " × " + name + "; the limit is " + x.max + ".");
  }
  return issues;
}

/** "Leader + 9 operatives", from what the data encodes. */
export function compositionLabel(t) {
  if (!t) return "";
  const c = t.composition && t.composition.operative;
  const lead = t.operatives.some((x) => x.leader) ? "Leader + " : "";
  if (!c) return "";
  const n = c.min === c.max || c.max == null ? c.min : c.min + "–" + c.max;
  return lead + n + " operative" + (n === 1 ? "" : "s");
}
